import {Client} from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/index.js';
import {StdioClientTransport} from '/harness-state/.bun/install/global/node_modules/@modelcontextprotocol/sdk/dist/esm/client/stdio.js';
import fs from 'node:fs';
const config=JSON.parse(fs.readFileSync('/harness-state/openclaw/openclaw.json','utf8')).mcp.servers.gbrain;
const client=new Client({name:'gbrain-install-roundtrip',version:'1.0.0'});
const transport=new StdioClientTransport({command:config.command,args:config.args,cwd:config.cwd,env:{...process.env,...config.env},stderr:'inherit'});
const marker='amber-compass-4e39bd72';
async function call(name,args){const result=await client.callTool({name,arguments:{...args,_meta:{hot_memory:'off'}}}); console.log(JSON.stringify({tool:name,result}));if(result.isError)throw Error(JSON.stringify(result));return JSON.parse(result.content.find(x=>x.type==='text').text);}
try{
 await client.connect(transport);
 const saved=await call('remember',{fact:`Synthetic MCP verification note: ${marker}; not a fact about the user.`,entity:'install-check-mcp',provenance:'install-check',kind:'fact'});
 const id=String(saved.id??saved.outcome?.id??saved.write_request?.id??'');
 if(!id)throw Error('No committed fact ID returned; inspect receipt before retry');
 fs.writeFileSync('/tmp/gbrain-install-docs/mcp-test-id.txt',id);
 const found=await call('recall',{entity:'install-check-mcp'});
 if(!JSON.stringify(found).includes(marker))throw Error('MCP readback missing marker');
 await client.close();
 const again=new Client({name:'gbrain-install-reopen',version:'1.0.0'});
 const second=new StdioClientTransport({command:config.command,args:config.args,cwd:config.cwd,env:{...process.env,...config.env},stderr:'inherit'});
 await again.connect(second);
 async function reopened(name,args){const r=await again.callTool({name,arguments:{...args,_meta:{hot_memory:'off'}}});console.log(JSON.stringify({stage:'new-server-process',tool:name,result:r}));if(r.isError)throw Error(JSON.stringify(r));return JSON.parse(r.content.find(x=>x.type==='text').text);}
 try{
 const persisted=await reopened('recall',{entity:'install-check-mcp'});if(!JSON.stringify(persisted).includes(marker))throw Error('Persistence read missing marker');
 await reopened('forget',{id,reason:'install-check cleanup'});
 const cleaned=await reopened('recall',{entity:'install-check-mcp'});if(JSON.stringify(cleaned).includes(marker))throw Error('Withdrawn marker still active');
 console.log(JSON.stringify({verification:'passed',id,remember:true,recall:true,new_process_recall:true,forget:true,active_cleanup:true}));
 }finally{await again.close();}
}finally{await client.close();}

